var DP_Meldung_Proxmox, title, DP_Verlauf, Meldung, Meldung_Verlauf, storage, DP_HTML, HTML, Max_Benachrichtigungen, Text_kuerzen, j, Speicher_Backup, severity, farbe;

// Beschreibe diese Funktion …
async function kuerzen(title) {
  if (String(title).includes('backup successful')) {
    title = 'Backup erfolgreich ';
  } else if (String(title).includes('backup failed')) {
    title = 'Backup fehlgeschlagen ';
  }
  return title;
}

function textReplace(haystack, needle, replacement) {
  needle = needle.replace(/([-()\[\]{}+?*.$\^|,:#<!\\])/g, '\\$1')
                 .replace(/\x08/g, '\\x08');
  return haystack.replace(new RegExp(needle, 'g'), replacement);
}

// Beschreibe diese Funktion …
async function speicher_backup() {
  if (String((Meldung[2])).includes('--storage ') && String((Meldung[1])).includes('backup')) {
    storage = Meldung[2].slice(((Meldung[2].indexOf('--storage') + 1 + 10) - 1), Meldung[2].indexOf('--storage') + 1 + 50);
    storage = textReplace(storage, '--', '\n');
    storage = storage.slice(0, storage.indexOf('\n') + 1);
    storage = ' - ' + String(storage);
  }
  return storage;
}


DP_Meldung_Proxmox = '0_userdata.0.Notification.Proxmox.notifications';
DP_Verlauf = '0_userdata.0.Notification.Proxmox.Letzte_Meldungen';
DP_HTML = '0_userdata.0.VIS.Tabellen.Protokoll_Proxmox';
Max_Benachrichtigungen = 20;
Text_kuerzen = true;
Speicher_Backup = true;

on({ id: '0_userdata.0.Notification.Proxmox.notifications', change: 'any' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  Meldung = getState(DP_Verlauf).val;
  Meldung.unshift(getState(DP_Meldung_Proxmox).val.split('***'));
  setStateDelayed(DP_Verlauf, { val: Meldung, ack: true }, parseInt(((0) || '').toString(), 10), false);
});

on({ id: [].concat(DP_Verlauf), change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  Meldung_Verlauf = getState(DP_Verlauf).val;
  HTML = '';
  Meldung_Verlauf = Meldung_Verlauf.slice(0, Max_Benachrichtigungen);
  var j_end = Meldung_Verlauf.length;
  var j_inc = 1;
  if (1 > j_end) {
    j_inc = -j_inc;
  }
  for (j = 1; j_inc >= 0 ? j <= j_end : j >= j_end; j += j_inc) {
    Meldung = Meldung_Verlauf[(j - 1)];
    severity = Meldung[0];
    if (severity == 'info') {
      farbe = '#33ff33';
    } else if (severity == 'notice') {
      farbe = '#ffff00';
    } else if (severity == 'warning') {
      farbe = '#ff6600';
    } else if (severity == 'error') {
      farbe = '#ff0000';
    } else if (severity == 'unknown') {
      farbe = '#ffff33';
    } else {
      farbe = '#ffff33';
    }
    HTML = String(HTML) + String(['<details>   <summary>',formatDate(getDateObject((parseFloat((Meldung[3])) * 1000)), 'TT.MM. SS:mm'),' <font color =',farbe,'>',severity,'</font> ',' ',Text_kuerzen ? await kuerzen(Meldung[1]) : Meldung[1],Speicher_Backup ? await speicher_backup() : null,'','</summary> ',Meldung[2],'</details>'].join(''));
  }
  setStateDelayed(DP_HTML, { val: HTML, ack: true }, parseInt(((0) || '').toString(), 10), false);
});

